$('#actionsList').addEventListener('click',async e=>{const b=e.target.closest('[data-decision]');if(!b)return;if(b.dataset.decision==='approve'&&!confirm('Approve this action? ULTRON will create the calendar event or Gmail draft. It will not send email.'))return;b.disabled=true;try{const r=await req('/actions','PUT',{id:b.dataset.actionId,decision:b.dataset.decision});toast(b.dataset.decision==='approve'?'Approved action completed.':'Action rejected.');loadActions()}catch(err){toast(err.message)}finally{b.disabled=false}});
async function refreshMissionControl(){const b=$('#missionRefresh');if(b)b.disabled=true;try{await Promise.all([loadItems(),loadActions()]);const open=items.filter(x=>['task','reminder'].includes(x.kind)&&x.status==='open');const pending=$('#actionsList').querySelectorAll('.actioncard').length;$('#missionTasks').textContent=open.length+' OPEN';$('#missionApprovals').textContent=pending+' PENDING';$('#missionBrief').textContent=$('#briefText').textContent.toLowerCase().includes('no brief yet')?'NEEDS PREP':'READY';$('#missionUpdated').textContent='LAST SYNC '+new Date().toLocaleTimeString()}finally{if(b)b.disabled=false}}$('#missionRefresh').addEventListener('click',refreshMissionControl);setInterval(()=>{if(document.visibilityState==='visible')refreshMissionControl()},60000);async function loadMemories(){if(!settings.memory_enabled)return;try{const r=await req('/memory');const xs=r.memories||[];$('#memoriesList').innerHTML=xs.length?xs.map(m=>'<div class="memorycard"><div><strong>'+esc(m.category)+'</strong><p>'+esc(m.content)+'</p></div><button class="mini-delete" data-memory-id="'+esc(m.id)+'" aria-label="Delete memory">×</button></div>').join(''):'<div class="empty">No saved memories yet. Add one or tell ULTRON “remember this”.</div>'}catch(e){$('#memoriesList').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
$('#memoryForm').addEventListener('submit',async e=>{e.preventDefault();const content=$('#memoryContent').value.trim();if(!content)return;try{await req('/memory','POST',{category:$('#memoryCategory').value||'general',content});$('#memoryContent').value='';await loadMemories();toast('Saved to long-term memory.')}catch(err){toast(err.message)}});
$('#memoriesList').addEventListener('click',async e=>{const b=e.target.closest('[data-memory-id]');if(!b)return;if(!confirm('Delete this saved memory?'))return;try{await req('/memory','DELETE',{id:b.dataset.memoryId});loadMemories();toast('Memory deleted.')}catch(err){toast(err.message)}});
async function loadIntegrations(){try{const r=await req('/integrations');const state=(x)=>x.connected?'<span class="status-ok">Connected</span>':x.state==='needs_attention'?'<span class="status-warn">Needs attention</span>':'<span class="status-off">Not connected</span>';$('#connectionStatus').innerHTML='Google Calendar: '+state(r.calendar)+'<br>Gmail read: '+state(r.gmail)+'<br>Gmail drafts: '+state(r.gmail_compose)+'<br><a class="setupLink" href="https://hatchable.com/console/projects/ultron-ptje" target="_blank" rel="noopener">Manage OAuth connections in Hatchable Setup ↗</a>'}catch(e){$('#connectionStatus').textContent='Open Hatchable Setup to connect Google services.'}}
