let agentRuns=[];
function agentStatus(s,result){if(s==='completed')return result?.verificationStatus==='operationally_verified'?'OPERATIONS VERIFIED · FACTS NOT VERIFIED':result?.verificationStatus==='verified'?'VERIFIED COMPLETE':'COMPLETED · PARTIALLY VERIFIED';return ({queued:'QUEUED',running:'RUNNING',failed:'FAILED · REVIEW REQUIRED',cancelled:'CANCELLED'})[s]||String(s||'UNKNOWN').toUpperCase()}
function renderAgentRuns(){
 const box=$('#agentRuns');if(!box)return;
 $('#agentStatus').textContent=agentRuns.filter(x=>['queued','running'].includes(x.status)).length+' active · '+agentRuns.length+' recent mission(s) · free-first execution';
 box.innerHTML=agentRuns.length?agentRuns.map(r=>'<article class="evolution-item"><strong>'+esc(r.title)+'</strong><p>'+esc(r.objective||'No extra objective supplied.')+'</p><small>'+agentStatus(r.status,r.result)+' · '+new Date(r.created_at).toLocaleString()+(r.error?' · '+esc(r.error):'')+'</small><div class="agent-actions"><button class="secondary" data-agent-open="'+esc(r.id)+'">Inspect steps</button>'+(r.status==='queued'||r.status==='running'?'<button class="secondary" data-agent-action="cancel" data-id="'+esc(r.id)+'">Cancel</button>':'')+(r.status==='failed'||r.status==='cancelled'?'<button class="secondary" data-agent-action="retry" data-id="'+esc(r.id)+'">Retry</button>':'')+'</div></article>').join(''):'<div class="empty">No agent missions yet. Create one above to start ULTRON’s execution cycle.</div>';
}
async function loadAgentRuns(){
 try{
  agentRuns=(await req('/agent')).runs||[];renderAgentRuns();
  const completed=agentRuns.filter(x=>x.status==='completed').length,failed=agentRuns.filter(x=>x.status==='failed').length,verified=agentRuns.filter(x=>x.status==='completed'&&x.result?.verificationStatus==='operationally_verified').length;
  const lessons=agentRuns.reduce((n,x)=>n+Number(x.result?.learning?.distinctApprovedLessonsConsulted||0),0);
  $('#agentMetricRuns').textContent=agentRuns.length;
  $('#agentMetricCompleted').textContent=completed;
  $('#agentMetricVerified').textContent=verified;
  $('#agentMetricFailed').textContent=failed;
  $('#agentMetricLessons').textContent=lessons;
  $('#agentStatus').textContent=agentRuns.filter(x=>['queued','running'].includes(x.status)).length+' active · '+agentRuns.length+' recent mission(s) · '+(completed+failed?Math.round(completed/(completed+failed)*100)+'% completion rate':'no completed outcomes yet')+' · free-first execution';
 }catch(e){$('#agentStatus').textContent='Agent engine unavailable: '+e.message}
}
async function inspectAgentRun(id){
 const d=await req('/agent?id='+encodeURIComponent(id)),r=d.run,steps=d.steps||[];
 $('#agentRunDetail').innerHTML='<strong>'+esc(r.title)+' · '+agentStatus(r.status,r.result)+'</strong><p>'+esc(r.objective||'No objective supplied.')+'</p>'+(r.result&&r.result.verificationStatus?'<p class="tiny">Operation checks: '+esc(r.result.stepsVerified||0)+' of '+esc(r.result.stepsCompleted||0)+' steps passed. This confirms execution and persistence checks only; factual accuracy remains separately unverified.</p>':'')+(r.result&&r.result.learning?'<p class="tiny">Approved lessons consulted: '+esc(r.result.learning.distinctApprovedLessonsConsulted||0)+' distinct lesson(s) across '+esc(r.result.learning.stepsWithApprovedLessons||0)+' step(s).</p>':'')+steps.map(s=>'<article class="agent-step"><b>'+s.position+'. '+esc(s.title)+'</b><small>'+esc(s.step_type)+' · '+esc(s.status.toUpperCase())+'</small>'+(s.error?'<p>'+esc(s.error)+'</p>':'')+(s.result&&s.result.learningContext&&s.result.learningContext.count?'<p class="tiny">Owner-approved lessons consulted: '+esc(s.result.learningContext.count)+' (matching step type only).</p>':'')+(s.result&&Object.keys(s.result).length?'<pre>'+esc(JSON.stringify(s.result,null,2).slice(0,5000))+'</pre>':'')+'</article>').join('')+'<small class="tiny">Created '+new Date(r.created_at).toLocaleString()+' · Attempts '+r.attempts+'</small>';
}
$('#agentForm').addEventListener('submit',async e=>{
 e.preventDefault();const b=e.submitter;b.disabled=true;b.textContent='Queuing mission…';
 try{
  const title=$('#agentTitle').value.trim(),objective=$('#agentObjective').value.trim(),query=$('#agentQuery').value.trim(),verifyUrl=$('#agentVerifyUrl').value.trim(),topic=$('#agentLearnTopic').value.trim(),summary=$('#agentLearnSummary').value.trim(),taskTitle=$('#agentTaskTitle').value.trim(),skillId=$('#agentSkill').value,skillTask=$('#agentSkillTask').value.trim(),skillMetric=$('#agentSkillMetric').value.trim(),skillDirection=$('#agentSkillDirection').value,skillBaseline=$('#agentSkillBaseline').value;
  if(Boolean(topic)!==Boolean(summary))throw new Error('Enter both a learning topic and its summary, or leave both blank.');
  if(skillId&&(!skillTask||!skillMetric||skillBaseline===''))throw new Error('A mastered skill application needs a practical task, metric label and numeric baseline.');
  const steps=[];
  if(skillId)steps.push({type:'skill_apply',title:'Apply mastered skill in practical work',input:{skill_id:skillId,task_description:skillTask,metric_label:skillMetric,metric_direction:skillDirection,baseline_value:Number(skillBaseline)}});
  steps.push({type:'research_search',title:'Research the objective',input:{query}});
  if(verifyUrl)steps.push({type:'verify_url',title:'Verify the supplied source',input:{url:verifyUrl}});
  if(topic&&summary)steps.push({type:'save_learning',title:'Save verified learning',input:{topic,summary,source_url:verifyUrl}});
  if(taskTitle)steps.push({type:'create_task',title:'Apply the mission as a follow-up task',input:{title:taskTitle,body:objective}});
  if(steps.length>8)throw new Error('This mission has too many steps.');
  const r=await req('/agent','POST',{title,objective,steps});
  e.target.reset();await loadAgentRuns();await inspectAgentRun(r.runId);toast(r.workerQueued?'Mission saved and background execution queued.':'Mission saved; recovery worker will pick it up.');
 }catch(err){toast(err.message)}finally{b.disabled=false;b.textContent='Launch mission ↗'}
});
